package net.officefloor.hq.app.holiday;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedInUser;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/holidays")
@Validated
public class HolidayController {

    /** What the screen shows of a holiday: its date. */
    public record HolidayView(long id, LocalDate date) {
        static HolidayView of(Holiday holiday) {
            return new HolidayView(holiday.getId(), holiday.getDate());
        }
    }

    /** A holiday's date, as entered on the form. */
    public record HolidayForm(@NotNull LocalDate date) {
    }

    private final HolidayService service;

    public HolidayController(HolidayService service) {
        this.service = service;
    }

    /** The sheet's holidays in date order. */
    @GetMapping
    public List<HolidayView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(HolidayView::of).toList();
    }

    /** Add a holiday to the sheet. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public HolidayView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid HolidayForm form) {
        return HolidayView.of(service.add(sheetId.trim(), SignedInUser.name(user), form.date()));
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

export interface HolidayView {
  id: number;
  /** The holiday (yyyy-mm-dd). */
  date: string;
}

// The holidays of a sheet, as the store holds them.
@Injectable({ providedIn: 'root' })
export class HolidaysApi {
  private readonly http = inject(HttpClient);

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/holidays`;
  }

  /** The sheet's holidays in date order. */
  list(sheetId: string): Promise<HolidayView[]> {
    return firstValueFrom(this.http.get<HolidayView[]>(this.url(sheetId)));
  }

  /** Add a holiday: refused when the date is already one. */
  add(sheetId: string, date: string): Promise<HolidayView> {
    return firstValueFrom(this.http.post<HolidayView>(this.url(sheetId), { date }));
  }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { HolidayView, HolidaysApi } from './holidays-api';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

// The sheet's holidays in date order, with an entry to add one. A claim's terms count business
// days, skipping every Saturday, Sunday and holiday on the sheet now, so adding one moves every
// due-by it falls before.
@Component({
  selector: 'app-holidays',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="holidays-heading">
      <h2 id="holidays-heading">Holidays</h2>
      <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Add a holiday">
        <label for="holiday-date">Date</label>
        <input id="holiday-date" type="date" data-testid="holiday-date" formControlName="date" />
        <button type="submit" data-testid="holiday-add" [disabled]="saving()">Add holiday</button>
        @if (error()) {
          <p role="alert" data-testid="holiday-error">{{ error() }}</p>
        }
      </form>
      <ul data-testid="holidays-list" aria-label="Holidays">
        @for (h of holidays(); track h.id) {
          <li [attr.data-testid]="'holiday-row-' + h.date">{{ h.date }}</li>
        }
      </ul>
    </section>
  `,
})
export class Holidays {
  private readonly session = inject(Session);
  private readonly api = inject(HolidaysApi);

  protected readonly date = new FormControl('', { nonNullable: true });
  protected readonly form = new FormGroup({ date: this.date });
  protected readonly holidays = signal<HolidayView[]>([]);
  protected readonly saving = signal(false);
  protected readonly error = signal('');

  constructor() {
    this.date.valueChanges.subscribe(() => this.error.set(''));
    // Each load of a sheet re-reads its holidays from the store and starts the entry afresh.
    effect(() => {
      const sheet = this.session.loaded();
      this.error.set('');
      this.date.reset('', { emitEvent: false });
      this.holidays.set([]);
      if (sheet) void this.load(sheet.id);
    });
  }

  private async load(sheetId: string): Promise<void> {
    try {
      const list = await this.api.list(sheetId);
      if (this.session.sheet()?.id === sheetId) this.holidays.set(list);
    } catch {
      if (this.session.sheet()?.id === sheetId) this.error.set('The holidays could not be loaded.');
    }
  }

  protected async submit(): Promise<void> {
    // A second submit before the first has answered is ignored, so it stores one record, not two.
    if (this.saving()) return;
    const sheet = this.session.sheet();
    if (!sheet) return;
    this.error.set('');
    const date = this.date.value.trim();
    if (!DATE.test(date)) {
      this.error.set('Type a date as yyyy-mm-dd.');
      return;
    }
    if (this.holidays().some((h) => h.date === date)) {
      this.error.set('That date is already a holiday.');
      return;
    }
    this.saving.set(true);
    try {
      const added = await this.api.add(sheet.id, date);
      if (this.session.sheet()?.id === sheet.id) {
        this.holidays.update((list) => [...list, added].sort((a, b) => a.date.localeCompare(b.date)));
        this.date.reset('', { emitEvent: false });
      }
    } catch (e) {
      if (this.session.sheet()?.id !== sheet.id) return;
      const status = e instanceof HttpErrorResponse ? e.status : 0;
      this.error.set(status === 409 ? 'That date is already a holiday.'
        : status === 403 ? 'Your role may not add a holiday on this sheet.' : 'The holiday could not be added.');
    } finally {
      this.saving.set(false);
    }
  }
}
import { Component, inject } from '@angular/core';
import { Session } from '../../core/session';
import { Holidays } from '../holidays/holidays';
import { People } from '../people/people';
import { Settings } from '../settings/settings';
import { SheetAsOf } from '../session/sheet-as-of';
import { SheetPicker } from '../session/sheet-picker';
import { SheetToday } from '../session/sheet-today';
import { SignIn } from '../session/sign-in';
import { VoidReasonsList } from '../void-reasons/void-reasons';

// The one screen: sign in, then choose a sheet; everything else is kept per sheet.
@Component({
  selector: 'app-home',
  imports: [SignIn, SheetPicker, SheetToday, SheetAsOf, Settings, Holidays, VoidReasonsList, People],
  template: `
    @if (session.user(); as user) {
      <header>
        Signed in as <strong data-testid="current-user">{{ user }}</strong>
      </header>
      <app-sheet-picker />
      <app-sheet-today />
      <app-sheet-as-of />
      @if (session.sheet()) {
        <app-settings />
        <app-holidays />
        <app-void-reasons />
      }
      <app-people />
      @if (!session.sheet()) {
        <p data-testid="home-empty">Load a sheet to begin.</p>
      }
    } @else {
      <app-sign-in />
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
}

